package com.xplayer.lite;
import android.content.*;
import org.json.*;
import java.util.*;
final class Backup {
 static final Set<String> bools=new HashSet<>(Arrays.asList("autoplay","auto_scan","thumbnails","folders","resume","auto_next","gestures","double_tap","keep_screen","noisy","subtitle_bg","history_enabled","auto_decoder","auto_subtitle","lite_mode","mark_last","scroll_last","select_thumbnail","floating_resume","recognize_nomedia","show_hidden","allow_edit","play_links","quit_button","double_back","resume_first","immersive","vertical_gestures","seek_gesture","gesture_osd","volume_boost","system_volume","system_volume_panel","eq_enabled","http","seek_preview","show_media_notification"));
 static final Set<String> strings=new HashSet<>(Arrays.asList("excluded","preferred_audio","preferred_subtitle","user_agent","quick_tools","scan_extensions"));
 static final Map<String,Integer> limits=new HashMap<>();static{limits.put("repeat_mode",2);limits.put("speed",8);limits.put("seek",3);limits.put("resize",2);limits.put("subtitle_size",3);limits.put("subtitle_color",2);limits.put("accent",3);limits.put("language",1);limits.put("background_mode",4);limits.put("new_period",4);limits.put("control_timeout",3);limits.put("decoder_local",2);limits.put("decoder_network",2);limits.put("cpu_cores",8);limits.put("subtitle_padding",3);limits.put("subtitle_font",3);limits.put("orientation",2);limits.put("audio_delay",10000);limits.put("subtitle_delay",10000);}
 static String exportJson(Context c)throws JSONException{JSONObject root=new JSONObject(),values=new JSONObject();root.put("version",1);root.put("settings",values);Map<String,?> all=ProPrefs.get(c).getAll();for(String k:bools)if(all.get(k) instanceof Boolean)values.put(k,all.get(k));for(String k:limits.keySet())if(all.get(k) instanceof Integer)values.put(k,all.get(k));for(String k:strings)if(all.get(k) instanceof String)values.put(k,all.get(k));for(String k:all.keySet())if(k.startsWith("decoder_ext_")&&all.get(k) instanceof Integer)values.put(k,all.get(k));return root.toString(2);}
 static void restore(Context c,String json)throws JSONException{JSONObject root=new JSONObject(json);if(root.getInt("version")!=1)throw new JSONException("Unsupported backup");JSONObject v=root.getJSONObject("settings");SharedPreferences.Editor e=ProPrefs.get(c).edit();for(String k:bools)if(v.has(k)&&v.get(k) instanceof Boolean)e.putBoolean(k,v.getBoolean(k));for(String k:limits.keySet())if(v.has(k)&&v.get(k) instanceof Number){int n=v.getInt(k);if(n>=(k.endsWith("_delay")?-10000:0)&&n<=limits.get(k))e.putInt(k,n);}for(String k:strings)if(v.has(k)&&v.get(k) instanceof String&&v.getString(k).length()<=20000)e.putString(k,v.getString(k));for(String ext:TreeScanner.extensions()){String k="decoder_ext_"+ext;if(v.has(k)&&v.get(k) instanceof Number){int n=v.getInt(k);if(n>=0&&n<=2)e.putInt(k,n);}}if(!e.commit())throw new JSONException("Save failed");}
}
